constexpr float PI=3.14159265358979323846f;
constexpr int MAX_DEPTH=32, MAX_DIMS=2+2*MAX_DEPTH, MAX_QUADS=256;
struct V {float x=0,y=0,z=0; __host__ __device__ V()=default; __host__ __device__ V(float a,float b,float c):x(a),y(b),z(c){} __host__ __device__ V operator+(V b)const{return {x+b.x,y+b.y,z+b.z};} __host__ __device__ V operator-(V b)const{return {x-b.x,y-b.y,z-b.z};} __host__ __device__ V operator-()const{return {-x,-y,-z};} __host__ __device__ V operator*(float a)const{return {x*a,y*a,z*a};} __host__ __device__ V operator/(float a)const{return *this*(1.f/a);} __host__ __device__ V mul(V b)const{return {x*b.x,y*b.y,z*b.z};}};
__host__ __device__ float dot(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}
__host__ __device__ V cross(V a,V b){return {a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};}
__host__ __device__ V unit(V a){float d=sqrtf(dot(a,a));return d>1e-12f?a/d:V{};}
__host__ __device__ float lum(V a){return .2126f*a.x+.7152f*a.y+.0722f*a.z;}
struct Quad {V p,u,v,color,light;};
struct Camera {V pos,forward,right,up;float fovScale,aspect;};
struct Sample {float primary[MAX_DIMS];V radiance;float importance;int pixel;};
struct Chain {curandStatePhilox4_32_10_t rng;Sample current;unsigned long long accepted;};
struct Config {int width=512,height=512,depth=8,bootstrap=100000,chains=4096,preview=1;long long mutations=100000000;unsigned long long seed=42;float fov=75,mouse=.0004f,persistence=.96f,move=1.5f,step=.012f,large=.3f,exposure=1;V position{0,1.5f,-2.5f},target{0,1.5f,3};std::string scene="labyrinth",output="laberinto.ppm";};
struct Scene {std::vector<Quad> q;void add(V p,V u,V v,V c,V e={}){q.push_back({p,u,v,c,e});}void box(V a,V b,V c){V u{b.x-a.x,0,0},v{0,b.y-a.y,0},w{0,0,b.z-a.z};add(a,u,v,c);add(a+w,u,v,c);add(a,u,w,c);add(a+v,u,w,c);add(a,v,w,c);add(a+u,v,w,c);}static Scene make(std::string name){Scene s;V white{.78f,.77f,.71f},stone{.64f,.67f,.72f},red{.70f,.19f,.16f},green{.17f,.62f,.38f},gold{.75f,.58f,.25f};if(name=="cornell"){s.add({-1,0,0},{0,2,0},{0,0,2},{.75f,.12f,.12f});s.add({1,0,0},{0,0,2},{0,2,0},{.12f,.70f,.15f});s.add({-1,0,2},{2,0,0},{0,2,0},white);s.add({-1,0,0},{2,0,0},{0,0,2},white);s.add({-1,2,0},{0,0,2},{2,0,0},white);s.add({-.34f,1.999f,.68f},{.68f,0,0},{0,0,.65f},{},{16,15,13});s.box({-.76f,0,.88f},{-.13f,.67f,1.54f},white);s.box({.18f,0,.45f},{.76f,1.22f,1.10f},white);}else{s.add({-4,0,-1},{8,0,0},{0,0,9},white);s.add({-4,3,-1},{0,0,9},{8,0,0},white);s.add({-4,0,8},{8,0,0},{0,3,0},stone);s.add({-4,0,-1},{0,3,0},{0,0,9},red);s.add({4,0,-1},{0,0,9},{0,3,0},green);s.box({-2.8f,0,.5f},{-2.55f,2.55f,4},stone);s.box({-2.8f,0,5.3f},{-2.55f,2.55f,7.1f},stone);s.box({-1,0,1.5f},{-.75f,2.55f,5.9f},white);s.box({.7f,0,.2f},{.95f,2.55f,2.7f},stone);s.box({.7f,0,4},{.95f,2.55f,7.7f},stone);s.box({2.45f,0,1.4f},{2.7f,2.55f,5.6f},white);s.box({-2.55f,0,3.8f},{-1.25f,2.3f,4.05f},gold);s.box({-.75f,0,6},{.5f,2.4f,6.25f},stone);s.box({1.1f,0,3.15f},{2.45f,2.3f,3.4f},white);s.box({-3.65f,0,6.9f},{-3.05f,1.1f,7.55f},gold);s.box({1.45f,0,6.45f},{2.1f,1.4f,7.05f},red);s.add({-3.6f,2.985f,0},{1.5f,0,0},{0,0,1.4f},{},{21,17,12});s.add({-.55f,2.985f,2.1f},{1.2f,0,0},{0,0,1.1f},{},{13,18,25});s.add({1.6f,2.985f,4.7f},{1.5f,0,0},{0,0,1.3f},{},{24,15,10});s.add({-2.2f,2.985f,6.6f},{1.3f,0,0},{0,0,1},{},{14,24,17});s.add({-3.98f,.65f,4.35f},{0,1.15f,0},{0,0,.18f},{},{9,13,22});s.add({3.98f,.6f,6.1f},{0,1.25f,0},{0,0,.20f},{},{23,13,8});}return s;}};
__device__ float rnd(curandStatePhilox4_32_10_t& r){return curand_uniform(&r)*0.99999994f;}
__device__ void evaluate(Sample& s,const Quad* quads,int nq,Camera camera,int w,int h,int depth){int px=min(w-1,int(s.primary[0]*w)),py=min(h-1,int(s.primary[1]*h));s.pixel=py*w+px;float fx=s.primary[0],fy=s.primary[1];V dir=unit(camera.forward+camera.right*((2*fx-1)*camera.aspect*camera.fovScale)+camera.up*((1-2*fy)*camera.fovScale));V pos=camera.pos,through{1,1,1},rad{};for(int bounce=0;bounce<depth;bounce++){float best=1e30f;int hit=-1;V normal{},point{};for(int i=0;i<nq;i++){Quad q=quads[i];V n=unit(cross(q.u,q.v));float den=dot(n,dir);if(fabsf(den)<1e-8f)continue;float t=dot(q.p-pos,n)/den;if(t<1e-4f||t>=best)continue;V delta=pos+dir*t-q.p;float a=dot(q.u,q.u),b=dot(q.u,q.v),c=dot(q.v,q.v),det=a*c-b*b;if(det<1e-12f)continue;float du=dot(delta,q.u),dv=dot(delta,q.v),u=(du*c-dv*b)/det,v=(dv*a-du*b)/det;if(u<0||u>1||v<0||v>1)continue;best=t;hit=i;normal=den<0?n:-n;point=pos+dir*t;}if(hit<0)break;Quad q=quads[hit];if(lum(q.light)>0){rad=rad+through.mul(q.light);break;}float angle=2*PI*s.primary[2+2*bounce],radius=sqrtf(s.primary[3+2*bounce]);V helper=fabsf(normal.x)>.5f?V{0,1,0}:V{1,0,0};V tangent=unit(cross(helper,normal)),bitangent=cross(normal,tangent);dir=unit(tangent*(cosf(angle)*radius)+bitangent*(sinf(angle)*radius)+normal*sqrtf(fmaxf(0.f,1-radius*radius)));through=through.mul(q.color);pos=point+normal*1e-4f;}s.radiance=rad;s.importance=fmaxf(0,lum(rad));}
__device__ void independent(Sample& s,curandStatePhilox4_32_10_t& rng,int dims,const Quad* q,int nq,Camera cam,int w,int h,int depth){for(int i=0;i<dims;i++)s.primary[i]=rnd(rng);evaluate(s,q,nq,cam,w,h,depth);}
__global__ void initChains(Chain* chains,int n,unsigned long long seed){int id=blockIdx.x*blockDim.x+threadIdx.x;if(id<n){curand_init(seed,id,0,&chains[id].rng);chains[id].accepted=0;}}
// Bootstrap estimates the image-wide normalization constant and provides weighted seeds.
__global__ void bootstrapKernel(Chain* chains,const Quad* q,int nq,Camera cam,int w,int h,int depth,int dims,int count,float* sums,Sample* seeds){int id=blockIdx.x*blockDim.x+threadIdx.x;if(id>=count)return;curandStatePhilox4_32_10_t rng;curand_init(0xB00757ULL,id,0,&rng);Sample s;independent(s,rng,dims,q,nq,cam,w,h,depth);sums[id]=s.importance;seeds[id]=s;}
__global__ void seedChains(Chain* chains,int n,const Sample* seeds,const float* cdf,int count,float total){int id=blockIdx.x*blockDim.x+threadIdx.x;if(id>=n)return;auto rng=chains[id].rng;float x=rnd(rng)*total;int lo=0,hi=count-1;while(lo<hi){int mid=(lo+hi)/2;if(cdf[mid]<x)lo=mid+1;else hi=mid;}chains[id].current=seeds[lo];chains[id].rng=rng;chains[id].accepted=0;}
__global__ void mutateKernel(Chain* chains,int n,const Quad* q,int nq,Camera cam,int w,int h,int depth,int dims,int iterations,float step,float large,float* accum,unsigned long long* acceptCount){int id=blockIdx.x*blockDim.x+threadIdx.x;if(id>=n)return;Chain chain=chains[id];unsigned long long accepted=0;for(int it=0;it<iterations;it++){Sample candidate=chain.current;bool big=rnd(chain.rng)<large;for(int k=0;k<dims;k++){float v=big?rnd(chain.rng):candidate.primary[k]+step*curand_normal(&chain.rng);candidate.primary[k]=v-floorf(v);}evaluate(candidate,q,nq,cam,w,h,depth);float a=chain.current.importance>0?fminf(1.f,candidate.importance/chain.current.importance):1.f;if(candidate.importance>0){float k=a/candidate.importance;atomicAdd(accum+candidate.pixel*3,candidate.radiance.x*k);atomicAdd(accum+candidate.pixel*3+1,candidate.radiance.y*k);atomicAdd(accum+candidate.pixel*3+2,candidate.radiance.z*k);}if(chain.current.importance>0){float k=(1-a)/chain.current.importance;atomicAdd(accum+chain.current.pixel*3,chain.current.radiance.x*k);atomicAdd(accum+chain.current.pixel*3+1,chain.current.radiance.y*k);atomicAdd(accum+chain.current.pixel*3+2,chain.current.radiance.z*k);}if(rnd(chain.rng)<a){chain.current=candidate;accepted++;}}chain.accepted+=accepted;chains[id]=chain;atomicAdd(acceptCount,accepted);}
class Preview {Display* d=nullptr;::Window win=0;GC gc=0;XImage* img=nullptr;Atom del=0;int w,h;bool quit=false,grab=false;std::array<bool,256> held{};float dx=0,dy=0;std::vector<float> trail;float persistence;static unsigned long channel(unsigned char v,unsigned long mask){if(!mask)return 0;int shift=0;while(((mask>>shift)&1UL)==0)shift++;unsigned long m=mask>>shift;return ((unsigned long(v)*m+127)/255)<<shift;}
public:Preview(int width,int height,bool enabled,float persist):w(width),h(height),persistence(persist){if(!enabled)return;d=XOpenDisplay(nullptr);if(!d){std::cerr<<"X11 unavailable; headless mode\n";return;}int screen=DefaultScreen(d);win=XCreateSimpleWindow(d,RootWindow(d,screen),30,30,w,h,0,0,BlackPixel(d,screen));XStoreName(d,win,"JOCARSA | CUDA PSSMLT");XSelectInput(d,win,ExposureMask|StructureNotifyMask|KeyPressMask|KeyReleaseMask|PointerMotionMask|ButtonPressMask);del=XInternAtom(d,"WM_DELETE_WINDOW",False);XSetWMProtocols(d,win,&del,1);XMapWindow(d,win);gc=XCreateGC(d,win,0,nullptr);img=XCreateImage(d,DefaultVisual(d,screen),DefaultDepth(d,screen),ZPixmap,0,nullptr,w,h,32,0);if(!img)throw std::runtime_error("XCreateImage failed");img->data=(char*)calloc(size_t(img->bytes_per_line)*h,1);if(!img->data)throw std::bad_alloc();trail.resize(size_t(w)*h*3);}
~Preview(){if(img)XDestroyImage(img);if(d){XFreeGC(d,gc);XDestroyWindow(d,win);XCloseDisplay(d);}}bool active()const{return d!=nullptr&&!quit;}bool exiting()const{return quit;}bool key(int sym)const{return sym>=0&&sym<256&&held[sym];}std::pair<float,float> mouse(){auto p=std::make_pair(dx,dy);dx=dy=0;return p;}void poll(){if(!active())return;while(XPending(d)){XEvent e;XNextEvent(d,&e);if(e.type==ClientMessage&&Atom(e.xclient.data.l[0])==del){quit=true;continue;}if(e.type==DestroyNotify){quit=true;continue;}if(e.type==KeyPress||e.type==KeyRelease){KeySym s=XLookupKeysym(&e.xkey,0);if(s==XK_Escape&&e.type==KeyPress)quit=true;if(s<256)held[s]=e.type==KeyPress;continue;}if(e.type==ButtonPress&&e.xbutton.button==Button1){grab=!grab;if(grab){XGrabPointer(d,win,True,PointerMotionMask|ButtonPressMask|ButtonReleaseMask,GrabModeAsync,GrabModeAsync,win,None,CurrentTime);XWarpPointer(d,None,win,0,0,0,0,w/2,h/2);}else XUngrabPointer(d,CurrentTime);}if(e.type==MotionNotify&&grab){if(e.xmotion.x==w/2&&e.xmotion.y==h/2)continue;dx+=e.xmotion.x-w/2;dy+=e.xmotion.y-h/2;XWarpPointer(d,None,win,0,0,0,0,w/2,h/2);}}}
void show(const std::vector<unsigned char>& rgb){if(!active())return;for(size_t i=0;i<rgb.size();i+=3){for(int c=0;c<3;c++)trail[i+c]*=persistence;if(rgb[i]||rgb[i+1]||rgb[i+2])for(int c=0;c<3;c++)trail[i+c]=rgb[i+c];}for(int y=0;y<h;y++)for(int x=0;x<w;x++){size_t i=(size_t(y)*w+x)*3;unsigned long pixel=channel((unsigned char)trail[i],img->red_mask)|channel((unsigned char)trail[i+1],img->green_mask)|channel((unsigned char)trail[i+2],img->blue_mask);XPutPixel(img,x,y,pixel);}XPutImage(d,win,gc,img,0,0,0,0,w,h);XFlush(d);}};
static Camera makeCamera(V pos,V forward,float fov,int w,int h){Camera c{};c.pos=pos;c.forward=unit(forward);c.right=unit(cross(c.forward,{0,1,0}));c.up=unit(cross(c.right,c.forward));c.fovScale=tanf(fov*PI/360);c.aspect=float(w)/h;return c;}
static unsigned char tone(float x){x=fmaxf(0,x);x=x/(1+x);return (unsigned char)std::clamp(int(powf(x,1/2.2f)*255+.5f),0,255);}
static std::vector<unsigned char> convert(const std::vector<float>& buf,float factor){std::vector<unsigned char> out(buf.size());for(size_t i=0;i<buf.size();i++)out[i]=tone(buf[i]*factor);return out;}
static void savePPM(const std::string& path,int w,int h,const std::vector<unsigned char>& rgb){std::ofstream f(path,std::ios::binary);if(!f)throw std::runtime_error("Cannot open output: "+path);f<<"P6\n"<<w<<" "<<h<<"\n255\n";f.write((const char*)rgb.data(),rgb.size());}
static void help(){std::cout<<R"(JOCARSA CUDA PSSMLT | Cornell / labyrinth
--scene cornell|labyrinth  --width N --height N --mutations N --depth N
--bootstrap N --chains N --seed N --camera-x V --camera-y V --camera-z V
--target-x V --target-y V --target-z V --fov V --preview 0|1
--mouse-sensitivity V --move-speed V --persistence V --small-step V
--large-prob V --exposure V --output FILE
--threads N accepted for CLI compatibility (ignored: CUDA controls GPU workers).
WASD movement, Q/E vertical, click capture mouse, ESC save and exit.
)";}
static Config parse(int argc,char** argv){Config s;for(int i=1;i<argc;i++){std::string k=argv[i];if(k=="--help"||k=="-h"){help();std::exit(0);}if(++i>=argc)throw std::runtime_error("Missing value for "+k);std::string v=argv[i];if(k=="--scene")s.scene=v;else if(k=="--width")s.width=std::stoi(v);else if(k=="--height")s.height=std::stoi(v);else if(k=="--mutations")s.mutations=std::stoll(v);else if(k=="--depth")s.depth=std::stoi(v);else if(k=="--bootstrap")s.bootstrap=std::stoi(v);else if(k=="--chains")s.chains=std::stoi(v);else if(k=="--seed")s.seed=std::stoull(v);else if(k=="--camera-x")s.position.x=std::stof(v);else if(k=="--camera-y")s.position.y=std::stof(v);else if(k=="--camera-z")s.position.z=std::stof(v);else if(k=="--target-x")s.target.x=std::stof(v);else if(k=="--target-y")s.target.y=std::stof(v);else if(k=="--target-z")s.target.z=std::stof(v);else if(k=="--fov")s.fov=std::stof(v);else if(k=="--preview")s.preview=std::stoi(v);else if(k=="--mouse-sensitivity")s.mouse=std::stof(v);else if(k=="--move-speed")s.move=std::stof(v);else if(k=="--persistence")s.persistence=std::stof(v);else if(k=="--small-step")s.step=std::stof(v);else if(k=="--large-prob")s.large=std::stof(v);else if(k=="--exposure")s.exposure=std::stof(v);else if(k=="--output")s.output=v;else if(k=="--threads"){/* compatibility */}else throw std::runtime_error("Unknown option: "+k);}if(s.scene!="cornell"&&s.scene!="labyrinth")throw std::runtime_error("Invalid scene");if(s.width<1||s.height<1||s.depth<1||s.depth>MAX_DEPTH||s.bootstrap<1||s.chains<1||s.chains>65536||s.mutations<1||s.fov<=1||s.fov>=170||s.persistence<0||s.persistence>=1||s.step<=0||s.large<0||s.large>1||s.exposure<=0||s.move<=0||s.mouse<=0)throw std::runtime_error("Invalid parameters");if(dot(s.target-s.position,s.target-s.position)<1e-6f)throw std::runtime_error("Camera and target coincide");return s;}
int main(int argc,char** argv){try{Config cfg=parse(argc,argv);int deviceCount=0;CUDA_CHECK(cudaGetDeviceCount(&deviceCount));if(deviceCount<1)throw std::runtime_error("No CUDA device found");cudaDeviceProp prop{};CUDA_CHECK(cudaGetDeviceProperties(&prop,0));std::cout<<"CUDA GPU: "<<prop.name<<" | compute "<<prop.major<<"."<<prop.minor<<"\n";Scene scene=Scene::make(cfg.scene);if(scene.q.size()>MAX_QUADS)throw std::runtime_error("Too many quads");Quad* dq=nullptr;Chain* dc=nullptr;float *dacc=nullptr,*dsums=nullptr;Sample* dseeds=nullptr;unsigned long long* daccepted=nullptr;size_t np=size_t(cfg.width)*cfg.height;CUDA_CHECK(cudaMalloc(&dq,scene.q.size()*sizeof(Quad)));CUDA_CHECK(cudaMemcpy(dq,scene.q.data(),scene.q.size()*sizeof(Quad),cudaMemcpyHostToDevice));CUDA_CHECK(cudaMalloc(&dc,size_t(cfg.chains)*sizeof(Chain)));CUDA_CHECK(cudaMalloc(&dacc,np*3*sizeof(float)));CUDA_CHECK(cudaMalloc(&dsums,size_t(cfg.bootstrap)*sizeof(float)));CUDA_CHECK(cudaMalloc(&dseeds,size_t(cfg.bootstrap)*sizeof(Sample)));CUDA_CHECK(cudaMalloc(&daccepted,sizeof(unsigned long long)));std::vector<float> host(np*3),weights(cfg.bootstrap);std::vector<unsigned char> last(np*3,0);Preview preview(cfg.width,cfg.height,cfg.preview,cfg.persistence);int block=128,grid=(cfg.chains+block-1)/block;initChains<<<grid,block>>>(dc,cfg.chains,cfg.seed);CUDA_CHECK(cudaGetLastError());CUDA_CHECK(cudaDeviceSynchronize());V f=unit(cfg.target-cfg.position);float yaw=atan2f(f.x,f.z),pitch=asinf(std::clamp(f.y,-1.f,1.f));auto previous=std::chrono::steady_clock::now(),lastShow=previous,start=previous;bool dirty=true,ready=false;long long completed=0;float normalization=1;unsigned long long accepted=0;int generation=0;
while(!preview.exiting()){preview.poll();if(preview.exiting())break;auto now=std::chrono::steady_clock::now();float dt=std::min(.1f,float(std::chrono::duration<double>(now-previous).count()));previous=now;auto m=preview.mouse();bool moved=false;if(m.first!=0||m.second!=0){yaw-=m.first*cfg.mouse;pitch=std::clamp(pitch-m.second*cfg.mouse,-1.54f,1.54f);moved=true;}V forward{sinf(yaw)*cosf(pitch),sinf(pitch),cosf(yaw)*cosf(pitch)},right=unit(cross(forward,{0,1,0})),planar=unit(V{forward.x,0,forward.z}),delta{};if(preview.key(XK_w)||preview.key(XK_W))delta=delta+planar;if(preview.key(XK_s)||preview.key(XK_S))delta=delta-planar;if(preview.key(XK_a)||preview.key(XK_A))delta=delta-right;if(preview.key(XK_d)||preview.key(XK_D))delta=delta+right;if(preview.key(XK_q)||preview.key(XK_Q))delta=delta-V{0,1,0};if(preview.key(XK_e)||preview.key(XK_E))delta=delta+V{0,1,0};if(dot(delta,delta)>0){cfg.position=cfg.position+unit(delta)*(cfg.move*dt);moved=true;}if(moved){dirty=true;ready=false;}Camera camera=makeCamera(cfg.position,forward,cfg.fov,cfg.width,cfg.height);
if(dirty){int count=moved?std::min(cfg.bootstrap,2048):cfg.bootstrap;CUDA_CHECK(cudaMemset(dacc,0,np*3*sizeof(float)));CUDA_CHECK(cudaMemset(daccepted,0,sizeof(unsigned long long)));bootstrapKernel<<<(count+block-1)/block,block>>>(dc,dq,int(scene.q.size()),camera,cfg.width,cfg.height,cfg.depth,2+2*cfg.depth,count,dsums,dseeds);CUDA_CHECK(cudaGetLastError());CUDA_CHECK(cudaMemcpy(weights.data(),dsums,size_t(count)*sizeof(float),cudaMemcpyDeviceToHost));double total=0;for(int i=0;i<count;i++){total+=weights[i];weights[i]=float(total);}if(total>0){float* dcdf=nullptr;CUDA_CHECK(cudaMalloc(&dcdf,size_t(count)*sizeof(float)));CUDA_CHECK(cudaMemcpy(dcdf,weights.data(),size_t(count)*sizeof(float),cudaMemcpyHostToDevice));seedChains<<<grid,block>>>(dc,cfg.chains,dseeds,dcdf,count,float(total));CUDA_CHECK(cudaGetLastError());CUDA_CHECK(cudaDeviceSynchronize());CUDA_CHECK(cudaFree(dcdf));normalization=float(total/count);completed=0;accepted=0;ready=true;dirty=false;start=std::chrono::steady_clock::now();generation++;}else{ready=false;dirty=true;}}
